/* 종합 리포트 줄글 엔진 (API 없이 미리 써 둔 완성 문단을 조합).
   규칙
   - 본문 문단에는 전문 용어(오행·일간·십성·하우스·다샤·개인년·인생 수 등)를 쓰지 않는다.
     화면(readingParts)이 이런 단어가 든 문장을 '근거'로 따로 빼기 때문. 근거는 basis 배열에만 넣는다.
   - 말투는 모두 "~해요".
   - 빈칸 {name} 등은 값만 바뀌고 문장 구조는 고정. */

const fill = (t, v) => t.replace(/\{(\w+)\}/g, (_, k) => (v[k] ?? ""));
const josa = (w, a, b) => { const c = String(w).trim().slice(-1).charCodeAt(0) - 0xac00; return (c >= 0 && c <= 11171 && c % 28) ? a : b; };
const pick = (arr, i) => arr[((i % arr.length) + arr.length) % arr.length];

