function weekHTML(ch){const ds=weekDays(),F=ds.map(d=>dayFortune(ch,d)),td=new Date().getDay(),ti=(td+6)%7;
  const hi=F.reduce((b,f,i)=>f.all>F[b].all?i:b,0),lo=F.reduce((b,f,i)=>f.all<F[b].all?i:b,0);
  const ca=[0,1,2,3].map(c=>F.reduce((a,f)=>a+f.sc[c],0)/7),bc=ca.indexOf(Math.max(...ca));
  const W=700,H=210,bw=56,gap=(W-40-bw*7)/6,y=v=>H-36-(v-55)/45*(H-70);
  const bars=F.map((f,i)=>{const x=20+i*(bw+gap),yy=y(f.all);return `<g class="wk${i===ti?" now":""}${i===hi?" hi":""}"><rect x="${x}" y="${yy}" width="${bw}" height="${H-36-yy}" rx="10"/><text x="${x+bw/2}" y="${yy-8}" text-anchor="middle" class="wk-v">${f.all}</text><text x="${x+bw/2}" y="${H-12}" text-anchor="middle" class="wk-d">${"월화수목금토일"[i]}${i===ti?"·오늘":""}</text></g>`}).join("");
  return `<div class="week"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="이번 주 요일별 점수">${bars}</svg>
  <ul class="wk-sum"><li><span>가장 좋은 날</span><b>${"월화수목금토일"[hi]}요일 (${F[hi].m}/${F[hi].d})</b><em>${F[hi].phrase}</em></li>
  <li><span>쉬어 갈 날</span><b>${"월화수목금토일"[lo]}요일 (${F[lo].m}/${F[lo].d})</b><em>${TARAM[F[lo].ta]}</em></li>
  <li><span>이번 주에 밝은 운</span><b style="color:var(--${CATS[bc].k})">${SHORT[bc]}운</b><em>일주일 평균 ${Math.round(ca[bc])}점</em></li></ul></div>`}
/* 귀인·결혼: 다섯 점술의 신호를 해마다 모아, 가장 많은 점술이 겹치는 해와 그해의 달·날짜까지 짚는다(자체 규칙). */
const PL_PERSON={Sun:"당당하고 리더십 있는",Moon:"다정하고 섬세한",Mars:"활동적이고 추진력 있는",Mercury:"재치 있고 말이 잘 통하는",Jupiter:"너그럽고 배울 점이 많은",Venus:"매력적이고 감각 있는",Saturn:"성실하고 책임감 강한",Rahu:"색다르고 이국적인 분위기의",Ketu:"조용하고 깊이가 있는"};
