function adPeriods(ch,y0,y1){const out=[];ch.dashas.forEach(md=>{let st=md.start;for(let k=0;k<9;k++){const L=(md.L+k)%9,len=DY[md.L]*DY[L]/120;if(st<y1&&st+len>y0)out.push({md:md.lord,lord:DL[L],s:st,e:st+len});st+=len}});return out}
const ymd=f=>{const y=Math.floor(f),m=Math.floor((f%1)*12)+1;return `${y}.${m}`};
