      const p=ads.find(p=>p.lord==="Venus"||p.lord===lord7);if(p)S.push(["베딕 점성술",`${PK[p.lord]} 보조 기간(${ymd(p.s)}~${ymd(p.e)})${p.lord===lord7?" · 7하우스(배우자) 주인":" · 사랑의 별"}`]);
      if(py===6||py===2)S.push(["수비학",`개인년 ${py}(${py===6?"사랑·가정":"협력·인연"})`]);
